<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin']);
$q=trim($_GET['q']??'');$params=[];$where='1';if($q!==''){$where.=" AND (a.action LIKE ? OR a.entity_type LIKE ? OR a.description LIKE ? OR u.name LIKE ?)";$like="%$q%";$params=[$like,$like,$like,$like];}
$rows=query_all("SELECT a.*,u.name user_name,u.role FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE $where ORDER BY a.created_at DESC LIMIT 250",$params);
$pageTitle='Audit Logs';include __DIR__.'/../includes/header.php';?>
<div class="table-card"><div class="table-toolbar"><form class="search" method="get"><i class="fa-solid fa-magnifying-glass"></i><input class="form-control form-control-sm" name="q" value="<?= e($q) ?>" placeholder="Search activity..."></form><div class="text-muted small"><?= count($rows) ?> recent actions</div></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= format_date($r['created_at'],'d M Y, h:i A') ?></td><td><strong><?= e($r['user_name']??'System') ?></strong><div class="text-muted" style="font-size:.64rem"><?= e($r['role']??'') ?></div></td><td><span class="badge-soft badge-info"><?= e($r['action']) ?></span></td><td><?= e($r['entity_type']??'—') ?><?= $r['entity_id']?' #'.(int)$r['entity_id']:'' ?></td><td><?= e($r['description']??'—') ?></td><td><?= e($r['ip_address']??'—') ?></td></tr><?php endforeach;?></tbody></table></div></div>
